```sql
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE films (
    id        SERIAL PRIMARY KEY,
    titre     TEXT NOT NULL,
    annee     INT,
    synopsis  TEXT,
    embedding vector(768)
);

CREATE INDEX ON films USING hnsw (embedding vector_cosine_ops);

SELECT titre, 1 - (embedding <=> (SELECT embedding FROM films WHERE id = 42)) AS similarite
FROM films
WHERE id <> 42
ORDER BY embedding <=> (SELECT embedding FROM films WHERE id = 42)
LIMIT 5;
```
